```python
def classify_triangle(sides):
    if len(sides) != 3:
        return 'invalid'
    a, b, c = sorted(sides)
    if a <= 0 or a + b <= c:
        return 'invalid'
    if a * a + b * b == c * c:
        return 'right'
    if a * a + b * b > c * c:
        return 'acute'
    return 'obtuse'
```

