def count_safe_orderings(start, transactions):
    from itertools import permutations
    count = 0
    for order in set(permutations(transactions)):
        balance = start
        ok = True
        for t in order:
            balance += t
            if balance < 0:
                ok = False
                break
        if ok:
            count += 1
    return count
